pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0) && _owner != address(c));
        vm.prank(c.owner());
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        bool success = ok ? abi.decode(ret, (bool)) : false;
        assertTrue(success);
    }
}
